toolArgs.file_text:
@page "/dashboard"
@rendermode InteractiveServer
@using sv_0ddd2ac6fabf46ef858902289ba234e5.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.LowStockCount == 0)
            {
                <span class="text-success fs-4">✓ No low-stock items</span>
            }
            else
            {
                <span class="text-danger fs-4">⚠ @AlertService.LowStockCount items below minimum levels</span>
            }
        </p>
        <p class="text-muted small">Refreshes every 10 seconds while this page is open.</p>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling when dashboard is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertService.StopPolling();
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

